import {isOffer,showOffer} from './offer.js';
import {manualCreateModal,readManualSelection} from './manual.js';
import {pricingHTML,mountPricing,readPricing,offerLinesHTML} from './pricing.js';
import {invoiceForm,invoiceInput} from './invoice.js';
import {downloadMigration} from './migration.js';
import {prepareProtocolPhotos} from './protocol-photos.js';
import {packages,extras,vehicleClasses} from './catalog.mjs';
const packageName=value=>packages.find(item=>item.id===value)?.name??value;
const extrasNames=values=>Array.isArray(values)?values.map(value=>extras.find(item=>item.id===value)?.name??value).join(', '):values;
const className=value=>vehicleClasses.find(item=>item.id===value)?.label??value;
const $=(s)=>document.querySelector(s);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(c)=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format((c??0)/100);
const date=(s,short=false)=>s?new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',...(short?{day:'2-digit',month:'2-digit'}:{dateStyle:'medium',timeStyle:'short'})}).format(new Date(s)):'—';
const localNow=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()).replace(' ','T');
const drawings=new Map();let state={orders:[],jobs:[],integrations:{},settings:{}},view='overview',selected=null,tab='source',synthetic=false,filter='Alle',query='',calendarOffset=0,protocolDraft=null;
const icons={home:'M3 10 12 3l9 7M5 9v11h14V9M9 20v-7h6v7',orders:'M5 5h14v16H5zM9 3h6v4H9zM8 11h8M8 15h5',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-3a4 4 0 0 0-3-4M16 2a4 4 0 0 1 0 8',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h1M13 14h1',docs:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',money:'M3 6h18v12H3zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M6 10v4M18 10v4',care:'M4 4h16v12H9l-5 4zM8 8h8M8 12h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',lock:'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4M12 15v2',plus:'M12 5v14M5 12h14',arrow:'M4 12h16M14 6l6 6-6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',warn:'M12 3 2 21h20zM12 9v5M12 17v1',check:'M4 12l5 5L20 6',car:'M4 15h16l-2-7H6zM3 15v5M21 15v5M6 17h1M17 17h1M7 8l1-4h8l1 4',mail:'M3 5h18v14H3zM3 5l9 7 9-7',menu:'M4 6h16M4 12h16M4 18h16',back:'M20 12H4M10 6l-6 6 6 6'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]??icons.docs}"/></svg>`;
const menus=[['overview','home','Übersicht'],['orders','orders','Anfragen & Aufträge'],['customers','people','Kunden'],['calendar','calendar','Kalender'],['protocols','docs','Fahrzeugprotokolle'],['finance','money','Rechnungen & Zahlung'],['care','care','Kundenbetreuung'],['settings','settings','Einstellungen']];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),7000);}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});const d=await r.json().catch(()=>({error:'Verbindung nicht lesbar.'}));if(!r.ok)throw Error(d.error??'Verbindung fehlgeschlagen.');return d;}
async function refresh(){state=await api('state');if(selected)selected=state.orders.find(o=>o.id===selected.id)??null;render();}
function list(){return state.orders.filter(o=>o.synthetic===synthetic).filter(o=>(o.wg+' '+o.source.name+' '+o.source.vehicle+' '+o.source.phone).toLowerCase().includes(query.toLowerCase()));}
function badge(status){return `<span class="badge ${['Preise prüfen','Angebot offen'].includes(status)?'warn':['Erledigt','Bezahlt'].includes(status)?'good':['Abgelehnt','Storniert','Abgelaufen'].includes(status)?'bad':''}">${esc(status)}</span>`;}
function next(o){return ({'Preise prüfen':'Fahrzeugzustand und Preise prüfen','Angebot offen':'Persönliche Kundenannahme abwarten','Angenommen':'Verbindlichen Termin festlegen','Termin verbindlich':'Annahmeprotokoll vervollständigen','In Arbeit':'Arbeit abschließen und Rückgabe dokumentieren','Erledigt':'Schlussrechnung und vollständige Zahlung','Bezahlt':'Auftrag abgeschlossen'})[o.status]??'Auftrag geschlossen';}
function empty(title,subtitle,button=''){return `<div class="empty"><div class="emptyicon">${icon('orders')}</div><strong>${esc(title)}</strong><p>${esc(subtitle)}</p>${button}</div>`;}
function heading(title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">White Gloss Detailing · Horb am Neckar</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function notice(title,body,blue=false){return `<div class="notice ${blue?'blue':''}">${icon(blue?'lock':'warn')}<div><strong>${title}</strong>${body}</div></div>`;}
function table(orders){return orders.length?`<div class="tablewrap"><table><thead><tr><th>Auftrag / Kunde</th><th>Fahrzeug</th><th>Status</th><th>Nächster Schritt</th><th>Festpreis</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr data-order="${o.id}"><td><strong>${esc(o.wg)}</strong><span class="sub">${esc(o.source.name)}</span></td><td>${esc(o.source.vehicle)}<span class="sub">${esc(packageName(o.source.package))}</span></td><td>${badge(o.status)}</td><td>${esc(next(o))}</td><td class="money">${o.offer?money(o.offer.totalCents):'Noch offen'}</td><td><button class="smallbtn" data-order="${o.id}">Öffnen</button></td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Aufträge',synthetic?'Erstelle einen eindeutig markierten Testauftrag. Es werden keine Kundennachrichten, Rechnungen oder Zahlungen ausgelöst.':'Dein neuer Bestand beginnt leer. Website-Anfragen werden nach geprüfter Verbindung und Nummernabgleich übernommen.',`<button data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Anfrage'} anlegen</button>`);}
function render(){const name=menus.find(m=>m[0]===view)?.[2]??'Übersicht';$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">WG</span><div><strong>White Gloss</strong><small>MEIN PANEL</small></div></div><div class="navgroup">DEIN BETRIEB</div><nav class="nav" aria-label="Hauptnavigation">${menus.map(m=>`<button data-view="${m[0]}" class="${m[0]===view?'active':''}" ${m[0]===view?'aria-current="page"':''}>${icon(m[1])}${m[2]}</button>`).join('')}</nav><footer><strong>White Gloss Detailing</strong>Horb am Neckar<br><br><span class="private">${icon('lock')} Privater Betreiberzugang</span></footer></aside><main class="workspace"><header class="topbar"><button class="mobile-menu" data-click="menu" aria-label="Menü öffnen">${icon('menu')}</button><div class="crumb">Mein Panel <span> / </span> <strong>${esc(name)}</strong></div><div class="top-actions"><span class="headerdate">${new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span><div class="search"><input id="search" placeholder="Auftrag oder Kunde suchen …" aria-label="Auftrag oder Kunde suchen" value="${esc(query)}"></div><button class="testswitch ${synthetic?'on':''}" data-click="test" aria-pressed="${synthetic}">${synthetic?'Testbereich aktiv':'Testbereich'}</button>${state.settings.standaloneAuth?'<button class="smallbtn" data-click="logout">Abmelden</button>':'<span class="avatar" title="Betreiber">WG</span>'}</div></header>${synthetic?'<div class="testbanner">Synthetische Testdaten · getrennte TEST-Nummern · kein Versand und keine Rechnungen</div>':''}<div class="content" id="content">${selected?detail():screen()}</div></main></div>`;mountDetail();$('#search')?.addEventListener('input',e=>{query=e.target.value;if(!selected)$('#content').innerHTML=screen();});}
function mountDetail(){mountPricing($('#priceform'));if(selected&&tab==='price'){const gallery=$('#websitephotos');if(gallery)loadBookingPhotos(gallery,selected.id);}}
async function loadBookingPhotos(gallery,id){try{gallery.textContent='Buchungsaufnahmen werden geladen …';const photoData=await api(state.settings.standaloneAuth?'bookingphotos?id='+encodeURIComponent(id):'websitephotos/'+id);const photos=Array.isArray(photoData)?photoData:photoData.photos;if(!gallery.isConnected)return;gallery.innerHTML=photos.length?photos.map(p=>p.mime.startsWith('image/')?`<a href="${esc(p.url)}" target="_blank" rel="noreferrer"><img src="${esc(p.url)}" alt="${esc(p.name)}"></a>`:`<video controls preload="metadata" src="${esc(p.url)}" aria-label="${esc(p.name)}"></video>`).join(''):'<p class="hint">Keine Buchungsaufnahmen vorhanden.</p>';if(photoData.warning)gallery.insertAdjacentHTML('beforeend','<p class="hint">'+esc(photoData.warning)+' · Geschützte Kopien bleiben verfügbar.</p>');}catch(error){gallery.textContent=error.message;}}
function screen(){switch(view){case'overview':return overview();case'orders':return ordersPage();case'customers':return customersPage();case'calendar':return calendarPage();case'protocols':return protocolsPage();case'finance':return financePage();case'care':return carePage();case'settings':return settingsPage();default:return overview();}}
function overview(){const orders=list(),open=orders.filter(o=>!['Bezahlt','Abgelehnt','Storniert','Abgelaufen'].includes(o.status)),price=orders.filter(o=>o.status==='Preise prüfen'),appointments=orders.filter(o=>o.appointment&&o.status==='Termin verbindlich');const revenue=orders.filter(o=>o.status==='Bezahlt').reduce((n,o)=>n+o.offer.totalCents,0);return heading('Dein Betrieb im Blick','Anfragen prüfen, Kunden begleiten und jeden Auftrag sicher abschließen.',`<button data-click="refresh">Aktualisieren</button><button class="primary" data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Neue Anfrage'}</button>`)+(!state.settings.numberAudit&&!synthetic?notice('Einrichtung abschließen','Für echte Aufträge fehlen noch der WG-Nummernabgleich und die benötigten Verbindungen. <a href="#settings" data-view="settings">Einstellungen öffnen →</a>'):'')+`<div class="stats">${[[open.length,'Offene Aufträge','Von der Anfrage bis zur Rückgabe','orders'],[price.length,'Preise prüfen','Deine Begutachtung ist gefragt','car'],[appointments.length,'Verbindliche Termine','Erst nach Kundenannahme','calendar'],[money(revenue),'Vollständig bezahlt','Tatsächlich dokumentierte Zahlungen','money']].map(([value,title,foot,ic])=>`<div class="card stat"><div class="top">${title}${icon(ic)}</div><div class="value money">${value}</div><div class="foot">${foot}</div></div>`).join('')}</div><div class="columns"><div><section class="card"><div class="card-title"><h2>Deine nächsten Schritte</h2><small>${open.length} offene Aufträge</small></div>${table(open.slice(0,6))}</section><section class="card sectiongap"><div class="card-title"><h2>Anstehende Termine</h2><button class="smallbtn" data-view="calendar">Kalender öffnen →</button></div>${appointments.length?appointments.slice(0,4).map(o=>`<div class="calendar-day" data-order="${o.id}"><strong>${date(o.appointment.start)}</strong><div class="calendar-item">${esc(o.wg)} · ${esc(o.source.name)}<br>${esc(o.source.vehicle)} · ${o.appointment.delivery}</div></div>`).join(''):empty('Noch keine verbindlichen Termine','Wunschdaten werden als Wünsche gespeichert. Ein verbindlicher Termin folgt erst nach Kundenannahme.')}</section></div><div><section class="card"><div class="card-title"><h2>Verbindungen & Freigaben</h2>${icon('lock')}</div><div class="card-body">${[['website','Website-Anfragen'],['calendar','Kalender'],['email','E-Mail-Versand'],['qonto','Qonto'],['customer','Kundenannahme'],['background','Hintergrundlauf']].map(([k,name])=>`<div class="integration"><div class="row"><span>${name}</span><span class="badge ${state.integrationReady?.[k]?'good':'warn'}">${state.integrationReady?.[k]?'Geprüft':'Einrichtung offen'}</span></div><p>${esc(state.integrations[k])}</p></div>`).join('')}<button data-view="settings" class="sectiongap">Einrichtung bearbeiten →</button></div></section><section class="card sectiongap"><div class="card-title"><h2>Dein Buchungsablauf</h2></div><div class="card-body"><ol class="step-list">${[['Anfrage & Preis','Fotos prüfen und Fixpreis festlegen'],['Kundenannahme','Persönliches Angebot mit Unterschrift'],['Termin & Annahme','Verbindlicher Termin und Fahrzeugprotokoll'],['Arbeit & Rückgabe','Abschluss und Rückgabe dokumentieren'],['Rechnung & Betreuung','Zahlung erfassen; Bewertung mit Einwilligung']].map(([t,s],i)=>`<li><span class="num">${i+1}</span><div>${t}<br><small>${s}</small></div></li>`).join('')}</ol></div></section></div></div><div class="endnote">Eigenständiger neuer Datenbestand · Europe/Berlin · Bestehende Apps bleiben unverändert</div>`;}
function ordersPage(){return heading('Anfragen & Aufträge','Jeder Auftrag folgt deinem festgelegten Ablauf.',`<button data-click="import">Website-Anfragen übernehmen</button><button class="primary" data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Neue Anfrage'}</button>`)+`<section class="card"><div class="toolbar">${['Alle','Preise prüfen','Angebot offen','Termin verbindlich','In Arbeit','Erledigt','Bezahlt'].map(s=>`<button data-filter="${s}" class="${filter===s?'active':''}">${s}</button>`).join('')}</div>${table(list().filter(o=>filter==='Alle'||o.status===filter))}</section>`;}
function customersPage(){const groups=new Map();for(const o of list()){const k=o.source.email||o.source.phone||o.source.name;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(o);}return heading('Deine Kunden','Kontaktdaten, Fahrzeuge und Betreuung aus deinem eigenen Auftragsbestand.')+(groups.size?`<div class="grid3">${[...groups.values()].map(os=>{const o=os[0];return `<div class="card customer-card"><h3>${esc(o.source.name)}</h3><p>${esc(o.source.email||'Keine E-Mail')}<br>${esc(o.source.phone||'Keine Telefonnummer')}<br>${esc(o.source.vehicle)}</p><span class="badge">${os.length} ${os.length===1?'Auftrag':'Aufträge'}</span><div class="actions sectiongap">${o.source.phone?`<a href="tel:${esc(o.source.phone.replace(/[^0-9+]/g,''))}">Anrufen</a>`:''}${o.source.email?`<a href="mailto:${esc(o.source.email)}">E-Mail öffnen</a>`:''}<button class="smallbtn" data-order="${o.id}">Kundenakte öffnen</button></div></div>`;}).join('')}</div>`:empty('Dein Kundenbestand ist noch leer','Kontaktdaten entstehen mit deinen neuen Anfragen. Es werden keine alten Hub-Aufträge übernommen.'));}
function calendarPage(){const today=new Date(new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'T12:00:00Z');const first=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()+calendarOffset,1,12));const offset=(first.getUTCDay()+6)%7;const count=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();const os=list().filter(o=>o.appointment&&!['Storniert','Abgelehnt'].includes(o.status));return heading('Dein Kalender','Verbindliche Termine in Europe/Berlin. Wünsche bestätigen noch keinen Termin.',`<a class="button" href="/api/calendar.ics${synthetic?'?test=true':''}" download>Termine als Kalenderdatei herunterladen</a>`)+notice('Kalenderdatei für Google oder Outlook','Du kannst verbindliche Termine als private Kalenderdatei herunterladen und importieren. Änderungen und Stornierungen müssen im externen Kalender abgeglichen werden. Der Export versendet keine Einladungen.',true)+`<div class="monthtitle"><h2>${new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric',timeZone:'Europe/Berlin'}).format(first)}</h2><div class="actions"><button data-click="prevMonth">←</button><button data-click="today">Heute</button><button data-click="nextMonth">→</button></div></div><div class="calendar-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(d=>`<div class="eyebrow">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendar-cell"></div>').join('')}${Array.from({length:count},(_,i)=>{const day=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),i+1,12)).toISOString().slice(0,10);return `<div class="calendar-cell ${day===today.toISOString().slice(0,10)?'today':''}">${i+1}${os.filter(o=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(o.appointment.start))===day).map(o=>`<div class="calendar-item" data-order="${o.id}">${date(o.appointment.start)}<br>${esc(o.source.name)}<br>${esc(o.source.vehicle)}</div>`).join('')}</div>`;}).join('')}</div>`;}
function protocolsPage(){const os=list().filter(o=>o.intake||o.return);return heading('Fahrzeugprotokolle','Annahme und Rückgabe mit Fotos, Zustand und zwei persönlichen Unterschriften.')+notice('Protokolle gehören zum Auftrag','Öffne einen Auftrag, um die Fahrzeugannahme oder Rückgabe zu dokumentieren. Bestätigte Protokolle bleiben erhalten; Ergänzungen erscheinen in der Kundenakte.',true)+(os.length?table(os):empty('Noch keine bestätigten Fahrzeugprotokolle','Ein Annahmeprotokoll wird nach dem verbindlichen Termin erstellt. Die Rückgabe folgt nach der Arbeit.'));}
function financePage(){const os=list().filter(o=>['Erledigt','Bezahlt'].includes(o.status));return heading('Rechnungen & Zahlung','Die WG-Nummer bleibt vom ersten Auftrag bis zur Schlussrechnung gleich.')+notice(state.settings.standaloneAuth?'Schlussrechnung nach Rückgabe':'Qonto-Einrichtung offen','Öffne einen abgeschlossenen Auftrag und prüfe Rechnungskunde, Adresse, Steuersatz und Festpreis vor Erstellung. Qonto und WG-Nummern müssen geprüft sein. „Bezahlt“ folgt ausschließlich nach dokumentiertem vollständigem Zahlungseingang.',state.settings.standaloneAuth)+`<section class="card"><div class="card-title"><h2>Abgeschlossene Aufträge</h2><small>Vollständige Zahlung mit Nachweis</small></div>${table(os)}</section>`;}
function carePage(){const notes=list().flatMap(o=>(o.notes??[]).map(n=>({...n,o}))).sort((a,b)=>b.at.localeCompare(a.at));return heading('Kundenbetreuung','Notizen, Rückfragen und Wiedervorlagen im Zusammenhang mit deinen Aufträgen.')+`<div class="columns"><section class="card"><div class="card-title"><h2>Betreuungsverlauf</h2></div>${notes.length?`<div class="card-body"><ul class="timeline">${notes.map(n=>`<li><small>${date(n.at)} · ${esc(n.o.wg)} · ${esc(n.kind)}${n.followUp?' · Wiedervorlage '+esc(n.followUp):''}</small><strong>${esc(n.o.source.name)}</strong><p>${esc(n.note)}</p><button class="smallbtn" data-order="${n.o.id}">Auftrag öffnen</button></li>`).join('')}</ul></div>`:empty('Noch keine Betreuungsnotizen','Öffne eine Kundenakte und halte Telefonate, Rückfragen oder nächste Schritte fest.')}</section><section class="card"><div class="card-title"><h2>Automatische Betreuung</h2></div><div class="card-body"><ol class="step-list"><li>${icon('clock')}<div>Terminerinnerung<br><small>Höchstens einmal, innerhalb der letzten 72 Stunden vor einem verbindlichen Termin.</small></div></li><li>${icon('mail')}<div>Bewertungsmail<br><small>Nur mit Einwilligung und frühestens 168 Stunden nach „Erledigt“. Keine zweite Nachfrage.</small></div></li><li>${icon('lock')}<div>Versandschutz<br><small>Dauerhafte Sperren verhindern Wiederholungen. Unklare Providerantworten verlangen einen Abgleich.</small></div></li></ol><p class="hint">${esc(state.integrations.background)} · ${esc(state.integrations.email)}</p>${state.jobs.length?`<ul class="timeline">${state.jobs.map(j=>`<li>${esc(j.kind)} · ${esc(j.state)}<small>${esc(j.detail??j.provider_id??'')}</small></li>`).join('')}</ul>`:''}</div></section></div>`;}
function input(label,name,type='text',value='',extra=''){return `<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function settingsPage(){const s=state.settings;return heading('Einstellungen & Verbindungen','Zugänge werden verschlüsselt gespeichert. Gespeichert bedeutet noch nicht geprüft.')+`<form id="settingsform"><section class="card formsection"><h2>WG-Nummern einmalig abgleichen</h2><p>Vergleiche vor dem ersten echten Auftrag den bisherigen Buchungsbestand und vorhandene Rechnungen. Bereits verwendete Nummern werden nie wieder vergeben.</p>${s.numberAudit?notice('Nummernstand abgeglichen',esc(s.numberEvidence),true):`<div class="grid2">${input('Letzte bereits vergebene WG-Nummer','lastNumber','number',s.lastNumber,'min="0" step="1"')}<label>Abgleichnachweis<textarea name="numberEvidence" placeholder="Welche bisherigen Buchungen und Qonto-Rechnungen wurden verglichen?">${esc(s.numberEvidence)}</textarea></label></div><label class="check"><input type="checkbox" name="numberAudit">Ich habe den bisherigen Nummernstand einschließlich vorhandener Rechnungen geprüft und bestätige die nächste freie Nummer.</label>`}</section><section class="card formsection"><h2>Website-Anfragen · ausschließlich lesen</h2><p class="hint">${esc(state.integrations.website)}</p><p>Beim ersten erfolgreichen Zugriff wird der Neustart festgehalten: vorhandene Anfragen werden ausgelassen. Danach maximal 40 Anfragen, neueste zuerst. Importierte Website-Angaben bleiben von deiner Begutachtung getrennt.</p>${input('Hub-Schlüssel','hubKey','password','','autocomplete="new-password" placeholder="'+(s.hubConfigured?'Bereits geschützt gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}<button type="button" data-check="website">Lesenden Zugriff prüfen</button><p class="hint">Keine Statusänderung, Bestätigung oder E-Mail auf white-gloss.de.</p></section><section class="card formsection"><h2>E-Mail-Versand · Resend</h2>${s.migrationReady?'<button type="button" data-click="migration">Geprüfte Resend-/Qonto-Zugänge verschlüsselt für IONOS übertragen</button>':''}<p>Verifizierte Absenderdomain erforderlich. Bei der Verbindungsprüfung wird keine E-Mail gesendet.</p><div class="grid2">${input('API-Schlüssel','resendKey','password','','autocomplete="new-password" placeholder="'+(s.resendConfigured?'Gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}${input('Verifizierte Absenderadresse','sender','email',s.sender)}</div>${input('Vorhandener Google-Bewertungslink','reviewUrl','url',s.reviewUrl)}<button type="button" data-check="email">Domain & Verbindung prüfen</button></section><section class="card formsection"><h2>Kalender</h2><p>Verbindliche Paneltermine werden nach geprüfter Google-Verbindung im Geschäftskalender angelegt oder aktualisiert. Änderungen aus Google werden nicht automatisch als Auftragsänderung übernommen.</p><div class="grid2"><label>Kalenderanbieter<select name="calendarProvider"><option ${s.calendarProvider==='Google'?'selected':''}>Google</option><option ${s.calendarProvider==='Outlook'?'selected':''}>Outlook</option></select></label>${input('Kalender-ID','calendarId','text',s.calendarId)}</div>${s.standaloneAuth?'':input('Zugriffstoken für lesende Prüfung','calendarToken','password','','autocomplete="new-password" placeholder="'+(s.calendarConfigured?'Gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}${s.standaloneAuth?'<button type="button" data-click="calendarConnect">Geschäftlichen Google-Kalender dauerhaft verbinden</button>':''}<button type="button" data-check="calendar">Lesenden Kalenderzugriff prüfen</button></section><section class="card formsection"><h2>Qonto</h2><p>Lesende Kontoprüfung. Rechnungsnummer, Steuerangaben und Rechnungsadapter müssen anschließend mit dem tatsächlichen Konto geprüft werden.</p><div class="grid2">${input('API-Login','qontoLogin','text',s.qontoLogin)}${input('API-Schlüssel','qontoKey','password','','autocomplete="new-password" placeholder="'+(s.qontoConfigured?'Gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}</div><button type="button" data-check="qonto">Lesende Qonto-Verbindung prüfen</button><button type="button" data-click="qontoNumbers">Vorhandene Rechnungsnummern lesen</button><p class="hint">${s.qontoNumberCheck?esc(s.qontoNumberCheck.count+' Rechnungen geprüft · höchste WG-Nummer '+s.qontoNumberCheck.maxNumber+' · abweichende WG-Formate '+s.qontoNumberCheck.otherWgNumbers):'Der Rechnungsabgleich bestätigt den Nummernstand erst zusammen mit deinem bisherigen Buchungsbestand.'}</p></section>${s.standaloneAuth?'<section class="card formsection"><h2>Dein Zugang</h2><p><a href="/auth/password">Passwort einrichten oder ändern</a></p></section><section class="card formsection"><h2>Automatische Abläufe freigeben</h2>'+[['sendApproved','Angebotsmails und automatische Kundenmails über den geprüften Absender erlauben'],['backgroundApproved','Terminerinnerungen und Bewertungsmails gemäß den festgelegten Fristen erlauben'],['autoImportApproved','Neue Website-Anfragen regelmäßig lesend übernehmen'],['calendarSyncApproved','Verbindliche Termine im geschäftlichen Google-Kalender abgleichen']].map(([key,label])=>'<label class="check"><input type="checkbox" name="'+key+'" '+(s[key]?'checked':'')+'>'+label+'</label>').join('')+'</section>':''}<div id="settings-error" class="error"></div><button class="primary" type="submit">Einstellungen geschützt speichern</button></form><section class="card formsection sectiongap"><h2>Angebote & Fälligkeiten prüfen</h2><p>${esc(state.integrations.background)}</p><p class="hint">${esc(s.lastBackgroundError??'Der Lauf prüft abgelaufene Angebote und fällige Vorgänge. Gesperrter Versand bleibt gesperrt.')}</p><button data-click="background">Jetzt prüfen</button></section><div class="sectiongap">${s.standaloneAuth?notice('Verbindungsstatus',Object.entries(state.integrations).map(([key,value])=>key+': '+value).join(' · '),true):notice('Kundenfreigabe','Für persönliche Kundenannahmen das jeweilige Konto gezielt in Sites als Betrachter berechtigen.')}</div>`;}
function detail(){const o=selected;const steps=['Preise prüfen','Angebot offen','Angenommen','Termin verbindlich','In Arbeit','Erledigt','Bezahlt'];return `<div class="actions" data-layout="back-actions"><button data-click="back">${icon('back')} Zurück</button></div><section class="card"><div class="detail-header"><div class="heading" data-layout="no-bottom"><div><div class="eyebrow">${esc(o.wg)} ${o.synthetic?'· Synthetischer Testauftrag':''}</div><h2>${esc(o.source.name)}</h2><p>${esc(o.source.vehicle)} · ${esc(packageName(o.source.package)||'Paket noch offen')}</p></div>${badge(o.status)}</div><div class="progress">${steps.map((_,i)=>`<span class="${i<=steps.indexOf(o.status)?'done':''}"></span>`).join('')}</div></div><div class="tabs" role="tablist">${[['source','Anfrage'],['price','Begutachtung & Angebot'],['appointment','Termin'],['intake','Annahme'],['return','Rückgabe'],['payment','Zahlung'],['notes','Kundenakte']].map(([id,name])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-tab="${id}">${name}</button>`).join('')}</div><div class="detail">${notice('Nächster Schritt',esc(next(o)),true)}${detailContent(o)}</div></section>`;}
function pairs(obj){return Object.entries(obj).map(([k,v])=>`<div class="fieldpair"><span>${k}</span><span>${esc(typeof v==='object'?JSON.stringify(v):v??'—')}</span></div>`).join('');}
function detailContent(o){switch(tab){case'source':return (o.source.id?'<button data-click="websitephotos">Fotos der Website-Anfrage ansehen</button><div class="photos sectiongap" id="websitephotos"></div>':'')+'<div class="sectiontitle">Originale Anfrageangaben</div>'+pairs({'Name':o.source.name,'Telefon':o.source.phone,'E-Mail':o.source.email,'Fahrzeug':o.source.vehicle,'Paket':packageName(o.source.package),'Fahrzeugklasse':className(o.source.vehicleClass),'Extras':extrasNames(o.source.extras),'Ort':o.source.city,'Adresse':o.source.address,'Hinweis':o.source.note,'Anfragebetrag':money(o.source.amountCents),'Abholung':(o.source.delivery?o.source.delivery+' · ':'')+money(o.source.pickupCents)+(o.source.pickupKm!==null&&o.source.pickupKm!==undefined?' · '+o.source.pickupKm+' km':''),'Wunschdatum':o.source.desiredDate,'Zeitfenster':o.source.timeWindow,'Bewertungsmail':o.source.reviewConsent?'Einwilligung vorhanden':'Keine Einwilligung','Website-ID':o.source.id??'Manuelle Anfrage'})+`<p class="hint">Website-Angaben sind keine eigene Begutachtung und bestätigen keinen verbindlichen Termin.</p>`;case'price':return priceDetail(o);case'appointment':return appointmentDetail(o);case'intake':return protocolDetail(o,'intake');case'return':return protocolDetail(o,'return');case'payment':return paymentDetail(o);case'notes':return notesDetail(o);}}
function priceDetail(o){const photos=(state.settings.standaloneAuth||o.source.id&&!o.synthetic?'<div class="sectiontitle">Buchungsfotos und Kundenwünsche</div><button data-click="bookingphotos">Buchungsaufnahmen aktualisieren</button><div class="photos sectiongap" id="websitephotos"></div>':'');const source=pairs({'Ursprüngliches Paket':packageName(o.source.package),'Kundenextras':extrasNames(o.source.extras),'Kundenhinweis':o.source.note,'Ursprünglicher Anfragepreis':money(o.source.amountCents),'Abholung laut Anfrage':money(o.source.pickupCents)});if(o.offer)return photos+offerLinesHTML(o.offer)+pairs({'Festpreis':money(o.offer.totalCents),'Leistungen':o.offer.services,'Begutachtung':o.offer.condition,'Gültig bis':date(o.offer.expiresAt),'Annahmestatus':o.status})+notice('Angebot ist unveränderlich','Die persönliche Kundenannahme erfolgt separat. Weitere Änderungen benötigen ein neues Angebot und eine erneute Kundenannahme.')+'<button data-click="offerLink">Persönlichen Angebotslink anzeigen</button>'+(state.settings.standaloneAuth&&!o.synthetic?'<button class="primary" data-click="sendOffer">Angebot per E-Mail senden</button>':'');return photos+source+pricingHTML(o)+(state.settings.standaloneAuth?'<form id="bookingphotoform" class="sectiongap"><label>Buchungsfotos ergänzen · JPEG, PNG, WebP · je bis 5 MB<input name="bookingphotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><button type="submit">Buchungsfotos geschützt speichern</button><div class="error" id="booking-photo-error"></div></form>':'');}
function appointmentDetail(o){if(!['Angenommen','Termin verbindlich'].includes(o.status))return notice('Termin noch nicht freigegeben','Ein verbindlicher Termin darf erst nach der persönlichen Kundenannahme gespeichert werden. Wunschdatum: '+esc(o.source.desiredDate||'nicht angegeben'));return `<form id="appointmentform"><div class="grid2">${input('Datum und Uhrzeit · Europe/Berlin','start','datetime-local',o.appointment?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(o.appointment.start)).replace(' ','T'):'','required')}${input('Dauer in Minuten','duration','number',o.appointment?.duration??120,'min="15" max="1440" step="15" required')}</div><div class="grid2"><label>Übergabeart<select name="delivery"><option>Abholung</option><option ${o.appointment?.delivery==='Kunde bringt'?'selected':''}>Kunde bringt</option></select></label>${input('Ort / Adresse','location','text',o.appointment?.location??o.source.address)}</div><p class="hint">Überschneidungen und ungültige Zeiten werden serverseitig abgelehnt. Eine Verschiebung erzeugt keine zweite Erinnerung.</p><button class="primary">Termin verbindlich speichern</button><div class="error" id="form-error"></div></form>${state.settings.standaloneAuth&&o.appointment&&!o.synthetic?'<button class="sectiongap" data-click="calendarSync">Verbindlichen Termin bei Google abgleichen</button>':''}`;}
function protocolMailStatus(o,kind){const job=state.jobs.find(j=>j.order_id===o.id&&j.kind==="protocol-"+kind);return notice("PDF-Versand",o.synthetic?"Testprotokoll: keine Kunden-E-Mail.":job?.state==="sent"?"Protokoll-PDF an den Kunden mit Kopie an dich versendet.":job?.detail??"Versandstatus im Ablaufprotokoll prüfen.",job?.state==="sent");}
function protocolDetail(o,kind){const saved=o[kind];if(saved)return '<div class="sectiontitle">Bestätigtes '+(kind==='intake'?'Annahmeprotokoll':'Rückgabeprotokoll')+'</div>'+pairs({'WG-Nummer':o.wg,'Betrieb':saved.business?.name,'Inhaber':saved.business?.owner,'Betriebsadresse':saved.business?saved.business.street+', '+saved.business.city:'—','Betriebsvertreter':saved.operatorName,'Unterschrift Kunde':saved.customerName,'Kunde':saved.customer,'Fahrzeug':saved.vehicle,'Kennzeichen':saved.plate,'Zeitpunkt':date(saved.at),'Ort':saved.location,'Übergabe':saved.delivery,'Kilometerstand':saved.mileage,'Schlüssel':saved.keys,'Zustand / Schäden':saved.condition,'Leistungen':saved.services??'—','Offene Punkte':saved.openPoints??'—','Protokollnachweis':saved.snapshotHash})+`<div class="photos sectiongap">${saved.photos.map(id=>`<img src="/api/asset/${id}" alt="Dokumentiertes Zustandsfoto">`).join('')}</div><div class="grid2 sectiongap"><div>Unterschrift Kunde<img class="signature" src="/api/asset/${saved.customerSignature}" alt="Unterschrift Kunde"></div><div>Unterschrift Betrieb<img class="signature" src="/api/asset/${saved.operatorSignature}" alt="Unterschrift Betrieb"></div></div>${state.settings.standaloneAuth&&saved.business?'<p><a href="/api/protocol/pdf?id='+encodeURIComponent(o.id)+'&kind='+kind+'">Unterschriebenes Protokoll als PDF herunterladen</a></p>'+protocolMailStatus(o,kind):''}<p class="hint">Bestätigte Protokolle bleiben erhalten. Ergänzungen über die Kundenakte dokumentieren.</p>`;if(kind==='intake'?o.status!=='Termin verbindlich':o.status!=='In Arbeit')return notice('Protokoll noch gesperrt',kind==='intake'?'Zuerst müssen Kundenannahme und verbindlicher Termin vorliegen.':'Zuerst muss das vollständige Annahmeprotokoll gespeichert sein.');return `${kind==='return'?'<details class="protocolreview"><summary>Vollständiges Annahmeprotokoll zum Vergleich</summary>'+pairs({'Kennzeichen':o.intake.plate,'Datum und Uhrzeit':date(o.intake.at),'Ort':o.intake.location,'Übergabeart':o.intake.delivery,'Kilometerstand':o.intake.mileage,'Schlüssel':o.intake.keys,'Zustand und Schäden':o.intake.condition,'Hinweise':o.intake.notes??'—'})+'<div class="photos">'+o.intake.photos.map(id=>'<img src="/api/asset/'+id+'" alt="Foto aus der Fahrzeugannahme">').join('')+'</div></details>':''}<p class="hint">${kind==='return'?'Annahme zum Vergleich: '+esc(o.intake?.condition??'')+' · '+esc(o.intake?.mileage??'')+' km · '+esc(o.intake?.keys??'')+' Schlüssel.':'Erst das vollständige Protokoll mit Fotos und beiden Unterschriften erlaubt „In Arbeit“.'}</p><form id="protocolform"><input type="hidden" name="kind" value="${kind}"><div class="grid2">${input('Kennzeichen','plate','text',o.intake?.plate??'','required')}${input('Datum / Uhrzeit · Europe/Berlin','at','datetime-local',localNow(),'required')}${input('Übergabeort','location','text',o.appointment?.location??'','required')}<label>Übergabeart<select name="delivery"><option ${o.appointment?.delivery==='Abholung'?'selected':''}>Abholung</option><option ${o.appointment?.delivery==='Kunde bringt'?'selected':''}>Kunde bringt</option></select></label>${input('Kilometerstand','mileage','number','','min="0" step="1" required')}${input('Anzahl Schlüssel','keys','number','','min="0" max="20" step="1" required')}${input('Name des Kunden','customerName','text',o.source.name,'required')}${input('Name des Betriebsvertreters','operatorName','text',state.company?.owner??'','required')}</div><label>Fahrzeugzustand / Schäden mit Position und Beschreibung<textarea name="condition" required></textarea></label><label>Zusätzliche Hinweise<textarea name="notes"></textarea></label>${kind==='return'?`<label>Ausgeführte Leistungen<textarea name="services" required>${esc(o.offer?.services??'')}</textarea></label><label>Offene Punkte<textarea name="openPoints"></textarea></label><label class="check"><input type="checkbox" name="workComplete" required>Die vereinbarten Arbeiten sind abgeschlossen.</label>`:''}<label>Zustandsfotos · JPEG, PNG, WebP · je maximal 5 MB<input type="file" id="protocolphotos" accept="image/jpeg,image/png,image/webp" multiple required></label><button class="primary" type="submit">Protokoll anzeigen & persönlich unterschreiben</button><div class="error" id="form-error"></div></form>`;}
function paymentDetail(o){const ps=o.payments??[],sum=ps.reduce((n,p)=>n+p.amountCents,0);if(!['Erledigt','Bezahlt'].includes(o.status))return notice('Rechnung und Zahlung noch gesperrt','Zuerst muss die Arbeit ausdrücklich abgeschlossen und das vollständige Rückgabeprotokoll gespeichert sein.');return pairs({'Festpreis':money(o.offer.totalCents),'Eingegangen':money(sum),'Noch offen':money(o.offer.totalCents-sum)})+`${o.invoice?'<p>Qonto-Schlussrechnung '+esc(o.invoice.number)+' · '+esc(o.invoice.status)+'</p>'+(o.invoice.url?'<a href="'+esc(o.invoice.url)+'" target="_blank" rel="noreferrer">Rechnung bei Qonto ansehen →</a>':''):state.settings.standaloneAuth&&!o.synthetic?'<button data-click="invoice">Qonto-Schlussrechnung vorbereiten</button>':'<button disabled>Qonto-Schlussrechnung · Einrichtung offen</button>'}${ps.length?'<ul class="timeline">'+ps.map(p=>`<li>${money(p.amountCents)} · ${esc(p.method)}<small>${date(p.at)} · ${p.method==='Bar'?'Bargeld ausdrücklich bestätigt':'Beleg vorhanden'}</small></li>`).join('')+'</ul>':''}${o.status!=='Bezahlt'?`<form id="paymentform" class="sectiongap"><div class="grid2">${input('Tatsächlich eingegangener Betrag in Cent','amountCents','number','','min="1" step="1" required')}${input('Zahlungszeitpunkt','at','datetime-local',localNow(),'required')}<label>Zahlungsart<select name="method"><option>Überweisung</option><option>Karte</option><option>Bar</option></select></label><label>Beleg (JPEG, PNG, WebP)<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp"></label></div><label class="check"><input name="cashConfirmed" type="checkbox">Bei Bargeld: Ich bestätige den tatsächlichen vollständigen Eingang dieses Teilbetrags.</label><button class="primary">Zahlung mit Nachweis speichern</button><div class="error" id="form-error"></div></form>`:''}`;}
function notesDetail(o){return `<form id="noteform"><div class="grid2"><label>Art<select name="kind"><option>Notiz</option><option>Telefonat</option><option>Rückfrage</option><option>Protokollergänzung</option><option>Wiedervorlage</option></select></label>${input('Wiedervorlage (optional)','followUp','date')}</div><label>Notiz / Ergänzung<textarea name="note" required placeholder="Besprochenes, Rückfrage oder nächsten Schritt festhalten"></textarea></label><button class="primary">In der Kundenakte speichern</button><div class="error" id="form-error"></div></form><div class="sectiontitle">Betreuungsverlauf</div><ul class="timeline">${(o.notes??[]).slice().reverse().map(n=>`<li><small>${date(n.at)} · ${esc(n.kind)}${n.followUp?' · Wiedervorlage '+esc(n.followUp):''}</small>${esc(n.note)}</li>`).join('')||'<li class="hint">Noch keine Notizen.</li>'}</ul><button data-click="audit">Änderungsprotokoll ansehen</button>${['Preise prüfen','Angebot offen','Angenommen','Termin verbindlich'].includes(o.status)?'<button class="danger" data-click="cancel">Auftrag stornieren</button>':''}${state.settings.standaloneAuth&&o.status==='Storniert'&&o.appointment&&!o.synthetic?'<button data-click="calendarSync">Google-Stornierung abgleichen</button>':''}${state.settings.standaloneAuth&&!o.synthetic?'<button data-click="reconcile">Anbieterresultat lesend prüfen</button>':''}`;}
function modal(title,content,footer=''){const m=$('#modal');m.innerHTML=`<div class="modalhead"><h2>${title}</h2><button data-click="close" aria-label="Schließen">×</button></div><div class="modalbody">${content}</div>${footer?`<div class="modalfooter">${footer}</div>`:''}`;m.showModal();}
function createModal(){manualCreateModal({synthetic,modal});}
async function action(action,input={}){const o=await api('action',{id:selected.id,version:selected.version,action,input});selected=o;await refresh();return o;}
async function uploadFile(file,kind='photo'){const r=await fetch('/api/upload/'+selected.id+'?kind='+kind+(kind==='signature'?'&draft='+protocolDraft.id+'&hash='+protocolDraft.hash:''),{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);return d.id;}
function signatureCanvas(id){const canvas=document.getElementById(id);canvas.width=900;canvas.height=300;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,900,300);ctx.strokeStyle='#263a4d';ctx.lineWidth=3;ctx.lineCap='round';let drawing=false;drawings.set(id,false);const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*900/r.width,(e.clientY-r.top)*300/r.height];};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke();drawings.set(id,true);};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;}
async function signatureFile(id){if(!drawings.get(id))throw Error('Beide Personen müssen persönlich unterschreiben.');return new File([await new Promise(resolve=>document.getElementById(id).toBlob(resolve,'image/png'))],id+'.png',{type:'image/png'});}
document.addEventListener('click',async e=>{const v=e.target.closest('[data-view]'),order=e.target.closest('[data-order]'),tb=e.target.closest('[data-tab]'),f=e.target.closest('[data-filter]'),check=e.target.closest('[data-check]'),click=e.target.closest('[data-click]');try{if(v){e.preventDefault();view=v.dataset.view;selected=null;render();return;}if(order){selected=state.orders.find(o=>o.id===order.dataset.order);tab='source';render();return;}if(tb){tab=tb.dataset.tab;render();return;}if(f){filter=f.dataset.filter;render();return;}if(check){$('#settings-error').textContent='';const form=$('#settingsform');const data=formData(form);const fields={website:['hubKey'],email:['resendKey','sender','reviewUrl'],calendar:['calendarProvider','calendarId','calendarToken'],qonto:['qontoLogin','qontoKey']}[check.dataset.check];check.disabled=true;try{await api('settings',Object.fromEntries(fields.map(k=>[k,data[k]])));const r=await api('check',{kind:check.dataset.check});toast(r.message);state=await api('state');for(const key of fields)if(form.elements[key]?.type==='password')form.elements[key].value='';}finally{check.disabled=false;}return;}if(!click)return;const k=click.dataset.click;if(k==='logout'){const response=await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw Error('Abmeldung nicht bestätigt.');location.assign('/auth/login');return;}if(k==='menu')$('.sidebar').classList.toggle('open');if(k==='close')$('#modal').close();if(k==='back'){selected=null;render();}if(k==='refresh')await refresh();if(k==='qontoNumbers'){const r=await api('qonto/numbers',{});await refresh();toast(r.count+' Rechnungen gelesen; höchste WG-Nummer '+r.maxNumber+'. Bisherige Buchungen zusätzlich abgleichen.');}if(k==='background'){const r=await api('background',{});await refresh();toast(r.deliveryError??'Angebote & Fälligkeiten geprüft.');}if(k==='migration'){const fingerprint=await downloadMigration();toast('Verschlüsselte Übertragung erstellt. Serverschlüssel: '+fingerprint.slice(0,16));}if(k==='calendarConnect'){const response=await fetch('/auth/calendar/start',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const result=await response.json();if(!response.ok)throw Error(result.error??'Google-Verbindung konnte nicht begonnen werden.');const authorization=new URL(result.authorizationUrl);if(authorization.origin!=='https://accounts.google.com'||authorization.pathname!=='/o/oauth2/v2/auth')throw Error('Google-Anmeldeziel konnte nicht geprüft werden.');location.assign(authorization.href);return;}if(k==='calendarSync'){await action('calendarSync');toast('Verbindlicher Google-Termin abgeglichen.');}if(k==='invoice'){const inventory=await api('qonto/clients?id='+encodeURIComponent(selected.id));modal('Schlussrechnung prüfen',invoiceForm(selected,inventory));}if(k==='sendOffer')modal('Angebot versenden',`<p>Empfänger: ${esc(selected.source.email)}</p><p>${esc(selected.wg)} · ${money(selected.offer.totalCents)} brutto</p><p>Der Kunde erhält den persönlichen Link und seine einmalige PIN in derselben E-Mail.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="sendOfferConfirmed">Angebot jetzt senden</button>`);if(k==='sendOfferConfirmed'){click.disabled=true;await action('sendOffer');$('#modal').close();toast('Resend hat den Angebotsversand bestätigt.');}if(k==='offerLink'){const link=location.origin+'/angebot/'+selected.offerToken;modal('Persönlicher Angebotslink',`<p>${esc(selected.source.name)} · ${esc(selected.source.email??'Kunden-E-Mail fehlt')}</p><label>Angebotslink<input readonly value="${esc(link)}"></label>${state.settings.standaloneAuth?'<p>Der Kunde erhält Link und einmalige PIN gemeinsam per E-Mail. Er sieht ausschließlich sein eigenes Angebot.</p>':'<p>Das Kundenkonto mit genau dieser E-Mail muss in der privaten Sites-Freigabe als Betrachter berechtigt werden. Der Link allein gewährt keinen Zugriff. Kunden sehen ausschließlich ihr eigenes Angebot.</p>'}<p class="hint">Der Betreiber kann das Angebot ansehen, aber nicht für den Kunden annehmen. Es wurde keine E-Mail versendet.</p>`);}if(k==='test'){synthetic=!synthetic;selected=null;render();}if(k==='create')createModal();if(k==='import'){if(synthetic)throw Error('Website-Import ist im Testbereich gesperrt.');const r=await api('import',{});toast(`${r.created} neue Anfragen, ${r.updated} aktualisiert, ${r.checked} geprüft, ${r.skipped??0} bestehende Anfragen ausgelassen.`);await refresh();}if(k==='confirm'&&$('#priceform')?.dataset.dirty==='true')throw Error('Bitte geänderte Leistungen und Preise zuerst speichern.');if(k==='confirm')modal('Fixpreis verbindlich bestätigen',`<p>Leistungen: ${esc(selected.assessment.services)}</p><p><strong>Gesamtfestpreis: ${money(selected.assessment.totalCents)}</strong></p><p class="hint">Nach Bestätigung bleibt das Angebot unveränderlich. Die persönliche Kundenannahme erfolgt separat.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="confirmPrice">Fixpreis bestätigen</button>`);if(k==='confirmPrice'){await action('confirm');$('#modal').close();toast('Fixpreis bestätigt. Angebot ist unveränderlich.');}if(k==='reject')modal('Anfrage ablehnen','<form id="rejectform"><label>Grund<textarea name="reason" required></textarea></label><button class="danger">Ablehnung speichern</button><div id="modal-error" class="error"></div></form>');if(k==='bookingphotos'){await loadBookingPhotos($('#websitephotos'),selected.id);}if(k==='websitephotos'){const photos=await api('websitephotos/'+selected.id);$('#websitephotos').innerHTML=photos.length?photos.map(p=>p.mime.startsWith('image/')?`<a href="${esc(p.url)}" target="_blank" rel="noreferrer"><img src="${esc(p.url)}" alt="${esc(p.name)}"></a>`:`<a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.name)} · Video öffnen</a>`).join(''):'<p class="hint">Keine Website-Fotos verfügbar.</p>';}if(k==='cancel')modal('Auftrag stornieren','<form id="cancelform"><label>Grund der Stornierung<textarea name="reason" required></textarea></label><p>Ein vorhandener eigener Google-Termin wird nach freigegebenem Kalenderabgleich aufgehoben. Kundennachrichten werden hier nicht versendet.</p><button class="danger">Stornierung speichern</button><div class="error" id="modal-error"></div></form>');if(k==='reconcile'){await action('reconcile');toast('Vorhandene Anbieterresultate gelesen. Offene Ergebnisse bleiben gegen Wiederholung gesperrt.');}if(k==='audit'){const audit=await api('audit');modal('Dauerhaftes Änderungsprotokoll','<ul class="timeline">'+audit.filter(a=>a.order_id===selected.id).map(a=>`<li><small>${date(a.at)} · ${esc(a.actor)} · Version ${a.version}</small>${esc(a.action)} → ${esc(a.status)}</li>`).join('')+'</ul>');}if(k==='prevMonth'){calendarOffset--;render();}if(k==='nextMonth'){calendarOffset++;render();}if(k==='today'){calendarOffset=0;render();}if(k==='clearCustomer'||k==='clearOperator')signatureCanvas(k==='clearCustomer'?'customerSign':'operatorSign');}catch(err){const el=$('#modal[open] #modal-error')??$('#form-error')??$('#settings-error');if(el)el.textContent=err.message;else toast(err.message);}});
function formData(form){return Object.fromEntries(new FormData(form));}
function settingsData(form){const d=formData(form);d.lastNumber=Number(d.lastNumber??0);d.numberAudit=form.elements.numberAudit?.checked===true;for(const key of ['sendApproved','backgroundApproved','autoImportApproved','calendarSyncApproved'])if(form.elements[key])d[key]=form.elements[key].checked;return d;}
document.addEventListener('submit',async e=>{if(isOffer)return;e.preventDefault();const f=e.target;const submit=f.querySelector('[type=submit]')??f.querySelector('button:not([type=button])');if(submit)submit.disabled=true;try{const d=formData(f);if(f.id==='settingsform'){await api('settings',settingsData(f));await refresh();toast('Einstellungen geschützt gespeichert. Verbindungen separat prüfen.');}if(f.id==='createform'){const selection=readManualSelection(f);delete d.extraIds;delete d.packageId;delete d.classId;delete d.citySlug;delete d.pickupKm;delete d.customPickupCents;d.reviewConsent=f.elements.reviewConsent.checked;selected=await api('create',{source:d,selection,synthetic});$('#modal').close();tab='source';await refresh();toast('Anfrage dauerhaft gespeichert.');}if(f.id==='priceform'){await action('price',readPricing(f));toast('Eigene Begutachtung gespeichert.');}if(f.id==='bookingphotoform'){for(const file of f.elements.bookingphotos.files){const response=await fetch('/api/upload/'+selected.id+'?kind=booking',{method:'POST',headers:{'Content-Type':file.type},body:file});const result=await response.json();if(!response.ok)throw Error(result.error);}await loadBookingPhotos($('#websitephotos'),selected.id);f.reset();toast('Buchungsfotos geschützt gespeichert.');}if(f.id==='invoiceform'){await action('invoice',invoiceInput(f));$('#modal').close();toast('Qonto-Schlussrechnung erstellt. Zahlung wird separat nachgewiesen.');}if(f.id==='appointmentform'){d.duration=Number(d.duration);await action('appointment',d);toast('Termin verbindlich gespeichert.');}if(f.id==='noteform'){await action('note',d);toast('Kundenakte ergänzt.');}if(f.id==='cancelform'){await action('cancel',d);$('#modal').close();toast('Stornierung gespeichert. Kalenderabgleich separat prüfen.');}if(f.id==='rejectform'){await action('reject',d);$('#modal').close();toast('Ablehnung gespeichert.');}if(f.id==='paymentform'){d.amountCents=Number(d.amountCents);d.at=berlinInputToISO(d.at);d.cashConfirmed=f.elements.cashConfirmed.checked;d.receipt=f.elements.receipt.files[0]?await uploadFile(f.elements.receipt.files[0]):null;await action('payment',d);toast('Tatsächlicher Zahlungseingang dokumentiert.');}if(f.id==='protocolform'){d.mileage=Number(d.mileage);d.keys=Number(d.keys);d.workComplete=f.elements.workComplete?.checked===true;Object.assign(d,await prepareProtocolPhotos($('#protocolphotos').files,uploadFile));protocolDraft=await api('protocol/prepare',{id:selected.id,version:selected.version,kind:d.kind,protocol:d});const reviewed=protocolDraft.protocol;modal('Protokoll prüfen & unterschreiben',`<div class="protocolreview">${pairs({'Betrieb':reviewed.business.name,'Inhaber':reviewed.business.owner,'Adresse':reviewed.business.street+', '+reviewed.business.city,'Kontakt':reviewed.business.phone+' · '+reviewed.business.email,'WG-Nummer':reviewed.wg,'Kunde':reviewed.customerName,'Betriebsvertreter':reviewed.operatorName,'Fahrzeug':reviewed.vehicle,'Kennzeichen':reviewed.plate,'Übergabezeit (Europe/Berlin)':reviewed.at,'Ort':reviewed.location,'Übergabeart':reviewed.delivery,'Kilometerstand':reviewed.mileage,'Schlüssel':reviewed.keys,'Zustand / Schäden':reviewed.condition,'Hinweise':reviewed.notes,'Leistungen':reviewed.services,'Offene Punkte':reviewed.openPoints})}<div class="photos">${reviewed.photos.map(id=>'<img src="/api/asset/'+id+'" alt="Zustandsfoto im angezeigten Protokoll">').join('')}</div></div><p class="hint">Die Unterschriften werden genau diesem angezeigten Protokoll zugeordnet. Bei Änderungen muss es neu angezeigt und unterschrieben werden.</p><form id="signatureform"><div class="grid2"><div class="signaturebox"><h3>Persönliche Unterschrift Kunde</h3><canvas id="customerSign" class="signature" aria-label="Unterschrift Kunde"></canvas><button type="button" data-click="clearCustomer">Löschen</button></div><div class="signaturebox"><h3>Unterschrift Betrieb</h3><canvas id="operatorSign" class="signature" aria-label="Unterschrift Betrieb"></canvas><button type="button" data-click="clearOperator">Löschen</button></div></div><label class="check sectiongap"><input type="checkbox" name="confirmed" required>Beide Personen haben dieses angezeigte Protokoll persönlich geprüft und unterschrieben.</label><div id="modal-error" class="error"></div><button type="submit" class="primary">Protokoll verbindlich speichern</button></form>`);signatureCanvas('customerSign');signatureCanvas('operatorSign');}if(f.id==='signatureform'){const customerSignature=await uploadFile(await signatureFile('customerSign'),'signature');const operatorSignature=await uploadFile(await signatureFile('operatorSign'),'signature');await action(protocolDraft.protocol.kind,{draftId:protocolDraft.id,snapshotHash:protocolDraft.hash,customerSignature,operatorSignature,signaturesConfirmed:f.elements.confirmed.checked});$('#modal').close();protocolDraft=null;toast('Protokoll und Unterschriften gespeichert. PDF-Versandstatus siehe Protokoll.');}}catch(err){const el=f.querySelector('.error')??$('#modal-error');if(el)el.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
function berlinInputToISO(local){const base=Date.parse(local+'Z');const fmt=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const matches=[60,120].map(n=>new Date(base-n*60000)).filter(d=>fmt.format(d).replace(' ','T')===local);if(matches.length!==1)throw Error('Uhrzeit ist ungültig oder bei der Zeitumstellung doppeldeutig.');return matches[0].toISOString();}
(isOffer?showOffer():refresh()).catch(err=>{$('#app').innerHTML=`<div class="appoff card"><span class="brandmark">WG</span><h1>Dein privates Panel</h1><p>${esc(err.message)}</p><p class="hint">Bitte mit deinem Betreiberkonto anmelden. Kundendaten werden ohne berechtigten Zugang nicht geladen.</p><button data-click="refresh">Erneut prüfen</button></div>`;});
